// Input Data Monitoring (CMP-01): validate each OPC UA sample published by
// the gateway before it reaches the edge data stock.
const p = msg.payload || {};
const fields = p.fields || {};
const tags = p.tags || {};
const machine = tags.machine_id || 'unknown';
const maxAbs = Number(env.get('INPUT_MAX_ABS') || 1e6);
const maxAgeS = Number(env.get('INPUT_MAX_AGE_S') || 86400);
const nowS = Date.now() / 1000;
const tsS = Number(p.timestamp || nowS);

const stats = flow.get('stats') || { valid: 0, rejected: {}, samples: 0, db_errors: 0, last_ts: 0 };
function reject(reason) {
    stats.rejected[reason] = (stats.rejected[reason] || 0) + 1;
    flow.set('stats', stats);
    node.warn(JSON.stringify({ component: 'edge-node-red', event: 'sample_rejected', reason, machine_id: machine, topic: msg.topic }));
    return [null, { topic: `plant/${machine}/rejected`, payload: { reason, sample: p } }];
}

if (typeof p !== 'object' || !p.fields) return reject('malformed');
if (fields.Quality && !String(fields.Quality).includes('Good')) return reject('bad_quality');
if (tsS > nowS + 60 || tsS < nowS - maxAgeS) return reject('implausible_timestamp');

const ts = [], machines = [], names = [], values = [];
for (const [k, v] of Object.entries(fields)) {
    if (k === 'Quality') continue;
    if (typeof v !== 'number' || !Number.isFinite(v)) return reject('not_numeric');
    if (Math.abs(v) > maxAbs) return reject('out_of_range');
    ts.push(new Date(tsS * 1000).toISOString()); machines.push(machine); names.push(k); values.push(v);
}
if (values.length === 0) return reject('empty');

stats.valid += 1; stats.samples += values.length; stats.last_ts = tsS;
flow.set('stats', stats);
msg.params = [ts, machines, names, values];
return [msg, null];

const stats = flow.get('stats') || { valid: 0, rejected: {}, samples: 0, db_errors: 0, last_ts: 0 };
stats.db_errors += 1;
flow.set('stats', stats);
node.warn(JSON.stringify({ component: 'edge-node-red', event: 'db_write_failed', error: String(msg.error && msg.error.message) }));
return null;

// Prometheus exposition of the input data monitoring counters.
const s = flow.get('stats') || { valid: 0, rejected: {}, samples: 0, db_errors: 0, last_ts: 0 };
const lines = [
  '# HELP ingest_messages_valid_total Samples that passed validation',
  '# TYPE ingest_messages_valid_total counter',
  `ingest_messages_valid_total ${s.valid}`,
  '# HELP ingest_values_written_total Values sent to the edge data stock',
  '# TYPE ingest_values_written_total counter',
  `ingest_values_written_total ${s.samples}`,
  '# HELP ingest_messages_rejected_total Samples rejected by validation',
  '# TYPE ingest_messages_rejected_total counter',
];
for (const [r, n] of Object.entries(s.rejected)) lines.push(`ingest_messages_rejected_total{reason="${r}"} ${n}`);
lines.push('# HELP ingest_db_errors_total Failed writes to the edge data stock',
           '# TYPE ingest_db_errors_total counter', `ingest_db_errors_total ${s.db_errors}`,
           '# HELP ingest_last_sample_timestamp_seconds Timestamp of the last valid sample',
           '# TYPE ingest_last_sample_timestamp_seconds gauge', `ingest_last_sample_timestamp_seconds ${s.last_ts}`);
msg.payload = lines.join('\n') + '\n';
return msg;
